export const foundationIds=['toy-project-2026','bottle-project-2026','clip-project-2026'];
export const planetaryId='planetary-project';
export function foundationsComplete(done,progress,projects){return foundationIds.every(id=>{const p=projects.find(x=>x.id===id),pr=progress[id];return done.has(id)||!!(p&&pr&&!pr.skipped&&Number(pr.step)>=p.steps.length);});}
export function gearMotion(sunDegrees){const carrier=sunDegrees/6;return {sun:sunDegrees,ring:0,carrier,planet:sunDegrees/-4,planetRelative:sunDegrees/-4-carrier};}
