export const planetaryProject={id:planetaryId,title:'מנגנון גלגלי שיניים פלנטרי',category:'פרויקט המשך',icon:'⚙',project:true,requires:foundationIds,refs:['PG1','PG2','PG3','PG4','PG5','PG6'],time:'60–90 דקות',intro:'עיבוד מודרך לסרטון RELUvance: בונים רכיבים, מרכיבים ומניעים ביחס 6:1. אפשר לעצור ולהמשיך מהמקום שלך.',result:'הרכבת מנגנון עם טבעת קבועה, שמש מניעה ושלושה לוויינים. לכל סיבוב של השמש הנשא מתקדם 60°. שמות הרכיבים שבחרת נשמרו.',steps,phases,end:{...ui,shape:'planet-animated'}};

// Equal pitch geometry; teeth are deliberately schematic polygons.
function gear(teeth,r,fill,hole=0){let points=[];for(let i=0;i<teeth*4;i++){const a=2*Math.PI*i/(teeth*4),rad=r+([0,3].includes(i%4)?-2.5:2.5);points.push([rad*Math.cos(a),rad*Math.sin(a)].map(n=>n.toFixed(2)).join(','));}return `<polygon points="${points.join(' ')}" fill="${fill}" stroke="#5d6c77" stroke-width=".8"/>${hole?`<circle r="${hole}" fill="#edf1f4" stroke="#64727d"/>`:''}<path d="M0 0H${r-5}" stroke="#536474" stroke-width="1.7"/>`;}
const centers=Array.from({length:3},(_,i)=>{const a=i*2*Math.PI/3;return [48*Math.cos(a),48*Math.sin(a)];});
export function planetaryGeometry(shape){
 const stage=['planet-empty','planet-ring-tool','planet-ring-blank','planet-ring','planet-one-origin','planet-one','planet-three','planet-sun','planet-shaft','planet-carrier-sketch','planet-carrier','planet-animated'].indexOf(shape),animated=shape==='planet-animated';
 let g='<path d="M70 205H490M280 18V392" stroke="#dae0e5" stroke-dasharray="4 4"/>';
 if(stage<1)return `<svg viewBox="0 0 855 403" aria-label="מנגנון חדש, מבט על">${g}<text x="280" y="230" text-anchor="middle" fill="#778692" font-size="12">XY · mm</text></svg>`;
 g+='<g transform="translate(280 205) scale(1.8)">';
 if(stage<3)g+=(stage===2?'<circle r="90" fill="#b9c6cf" stroke="#637887"/>':'')+gear(80,80,'#c1ccd3');
 if(stage>=3){g+='<circle r="90" fill="#9daebc" stroke="#546c7c"/><circle r="80" fill="#edf1f4" stroke="#627b8b"/>';for(let i=0;i<80;i++){g+=`<path d="M78.5 -1.8L82 -1.1L82 1.1L78.5 1.8Z" transform="rotate(${i*4.5})" fill="#a6b7c4" stroke="#627b8b" stroke-width=".35"/>`;}}
 if(stage===4)g+=gear(32,32,'#c8c0a6',4);
 if(stage>=5){g+='<g class="pg-orbit">';for(const [x,y] of centers.slice(0,stage===5?1:3)){g+=`<g transform="translate(${x} ${y})"><g class="pg-planet-spin">${gear(32,32,'#c9c1a8',4)}</g></g>`;}g+='</g>';}
 if(stage>=7)g+=`<g class="pg-sun">${gear(16,16,'#91b5ce',stage>=8?5:0)}</g>`;
 if(stage>=9){g+='<g class="pg-carrier" fill="#c6d6df" fill-opacity=".78" stroke="#5d798d">';for(const [x,y] of centers)g+=`<path d="M0 0L${x} ${y}" stroke="#7395ab" stroke-width="12" stroke-linecap="round"/>`;g+='<circle r="5.25" fill="#edf1f4"/>';for(const [x,y]of centers)g+=`<circle cx="${x}" cy="${y}" r="3.9" fill="#577e96"/>`;g+='</g>';}
 g+='</g><text x="280" y="388" text-anchor="middle" fill="#637787" font-size="11">TOP · סכמת תרגול, ללא פרופיל שן לייצור</text>';
 if(stage>=7)g+='<g font-family="Arial,sans-serif" fill="#556d7e" font-size="12"><text x="476" y="125">RING · 80</text><text x="476" y="151">SUN · 16</text><text x="476" y="177">PLANETS · 3 × 32</text><text x="476" y="203">MODULE · 2 mm</text><text x="476" y="229">RATIO · 6:1</text></g>';
 return `<svg viewBox="0 0 855 403" class="${animated?'pg-animated':''}" aria-label="מנגנון פלנטרי: טבעת 80, שמש 16, שלושה לוויינים 32, יחס 6 ל־1">${g}</svg>`;
}
export function planetarySpots(){const out={'planet-xy':[440,320,85,85],'planet-center':[471,355,28,28],'planet-sun-face':[465,349,40,40],'planet-carrier-plane':[450,333,70,70]};centers.forEach(([x,y],i)=>out['planet-'+(i+1)+'-center']=[471+x*1.8,355+y*1.8,28,28]);return out;}
